#include <Cellerator/compiler/reflection/implement_operation_replacement_and_ir_splicing_v1.hh>
namespace cellerator::compiler::reflection::v1 {
splice_status_v1 validate_operation_splice_v1(const std::vector<reflected_operation_v1>&g,const operation_splice_v1&s)noexcept{if(s.anchor>=g.size())return splice_status_v1::invalid_anchor;for(auto d:s.operand_definitions)if(d>=s.anchor&&s.kind!=splice_kind_v1::before)return splice_status_v1::dominance_violation;if(s.operation.effects!=g[s.anchor].effects&&(s.kind==splice_kind_v1::replace||s.kind==splice_kind_v1::wrap))return splice_status_v1::effect_violation;if(s.preserve_source_identity&&(s.operation.provenance.identity_high!=g[s.anchor].provenance.identity_high||s.operation.provenance.identity_low!=g[s.anchor].provenance.identity_low))return splice_status_v1::identity_violation;if(s.profile_state.empty())return splice_status_v1::profile_missing;for(auto r:s.results)if(r.old_result>=g[s.anchor].results.size()||r.new_result>=s.operation.results.size())return splice_status_v1::result_mismatch;return splice_status_v1::valid;}
std::vector<reflected_operation_v1> apply_operation_splice_v1(const std::vector<reflected_operation_v1>&g,const operation_splice_v1&s){auto r=g;if(validate_operation_splice_v1(g,s)!=splice_status_v1::valid)return r;if(s.kind==splice_kind_v1::before)r.insert(r.begin()+s.anchor,s.operation);else if(s.kind==splice_kind_v1::after)r.insert(r.begin()+s.anchor+1,s.operation);else if(s.kind==splice_kind_v1::replace)r[s.anchor]=s.operation;else{r.insert(r.begin()+s.anchor,s.operation);}return r;}
}
